from z3 import *

def solve(edges, name):
    n=12; m=21
    x=[Int(f'x{i}') for i in range(n)]
    d=[Int(f'd{i}') for i in range(m)]
    s=Solver()
    for xi in x: s.add(And(xi>=0, xi<=m))
    s.add(Distinct(x))
    for e,(u,v) in enumerate(edges):
        s.add(d[e] == If(x[u]>=x[v], x[u]-x[v], x[v]-x[u]))
        s.add(And(d[e]>=1,d[e]<=m))
    s.add(Distinct(d))
    s.add(x[2]==15, x[4]==0)
    for k,val in {6:5,9:11,15:13,18:9}.items(): s.add(d[k]==val)
    # Sym break maybe x4=0 already
    res=s.check()
    print(name, res)
    if res==sat:
        mod=s.model()
        sol=[mod.eval(xi).as_long() for xi in x]
        ds=[mod.eval(di).as_long() for di in d]
        print(sol)
        print(ds)
        print('edges fixed', [(k, edges[k], ds[k]) for k in [6,9,15,18]])
        return sol, ds

